const icons={pin:'<svg viewBox="0 0 24 24"><path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/></svg>',leaf:'<svg viewBox="0 0 24 24"><path d="M20 3C8 2 2 8 5 15s16 6 15-12Z"/><path d="m4 21 12-12"/></svg>',shield:'<svg viewBox="0 0 24 24"><path d="m12 2 8 3v6c0 6-8 11-8 11S4 17 4 11V5Z"/><path d="m8 11 3 3 5-6"/></svg>'};
const originalHome=home,originalCard=card,originalDetail=detail,originalRender=render;
function collectionSection(){return `<section class="section collections-section"><div class="container"><div class="section-heading"><div><span class="eyebrow">Thoughtfully matched to you</span><h2>Every traveller has a different journey.</h2><p>Start with what matters most to you.</p></div></div><div class="collection-grid">${[['01','Room for everyone','Family-friendly stays','Space to gather, rest, and reconnect.',images.home,'family'],['02','Close to the sacred','Near the ghats','Keep the heart of your pilgrimage nearby.',images.river,'ghats'],['03','Time to slow down','Peaceful retreats','A quieter base after a meaningful day.',images.resort,'retreat'],['04','Comfort, simply','Within your budget','Thoughtful stays with room in your budget.',images.room,'budget']].map(([n,e,t,d,img,key])=>`<button class="collection-tile" onclick="openCollection('${key}')"><img loading="lazy" src="${photo(img,700)}" alt="${key==='ghats'?'Ramkund ghats, Nashik':'Illustrative '+t.toLowerCase()}"><span class="collection-number">${n}</span><span class="collection-copy"><small>${e}</small><strong>${t}</strong><span>${d}</span></span><span class="round-arrow">↗</span></button>`).join('')}</div></div></section>`}
function openCollection(key){resetCollection();if(key==='family')state.capacity=4;if(key==='ghats'){state.destination='Panchavati / Ramkund';state.distance=1}if(key==='retreat')state.type='Premium Hotels & Resorts';if(key==='budget')state.max=2000;go('/stays')}
function resetCollection(){Object.assign(state,{destination:'All destinations',type:'All stays',capacity:1,distance:50,max:10000,amenities:[]})}
function faqSection(){return `<section class="section faq-section"><div class="container faq-layout"><div><span class="eyebrow">Before you begin</span><h2>A little clarity.<br>A more peaceful journey.</h2><p class="notice">Good stays begin with knowing what to expect.</p><a class="text-link" href="#/support">Visit our help centre ↗</a></div><div>${[['How do I choose where to stay?','Choose Panchavati / Ramkund for a base near the Godavari ghats, Trimbakeshwar for the temple area, or Nashik Road for transport convenience. Check the location and your travel arrangements before booking.'],['Can I find rooms for a family or a group?','Use the guest and room selectors to search for your party. Room capacity is shown on each property page. For larger groups, use the group enquiry form.'],['What should I check for older travellers?','Ask about steps, lifts, ground-floor rooms, bathroom access and vehicle drop-off. Accessibility information in this preview is not verified.'],['Will the total price be clear before payment?','The booking summary shows the room amount, number of nights, number of rooms and an illustrative tax amount before the demo payment step.'],['Can I make a real booking here?','This is a frontend preview. Listings, prices, ratings and availability are sample data. Payments, enquiries and reservations are simulated.']].map(([q,a])=>`<details class="premium-faq"><summary>${q}<span>+</span></summary><p>${a}</p></details>`).join('')}</div></div></section>`}
home=function(){let markup=originalHome();markup=markup.replace('<h1>A sacred journey.<br>A place to <em>belong.</em></h1>','<h1>Your sacred journey.<br>A stay to <em>remember.</em></h1>');markup=markup.replace('<p>Find your perfect stay for Nashik Kumbh 2027.<br>From peaceful homestays to thoughtfully chosen hotels, make room for what matters.</p>','<p>Thoughtful stays in Nashik & Trimbakeshwar.<br>Find your place of comfort, close to what brings you here.</p><a class="hero-guide" href="#/guide">Discover the journey <span>↗</span></a>');markup=markup.replace('<section class="section tinted">',collectionSection()+'<section class="section tinted">');markup=markup.replace('<section class="section"><div class="container"><div class="partner">',faqSection()+'<section class="section"><div class="container"><div class="partner">');return markup};
card=function(p){let html=originalCard(p),landmark=p.location==='Trimbakeshwar'?'Trimbakeshwar temple':'Ramkund';html=html.replace('<div class="amenities">',`<div class="stay-context"><span>${icons.pin}${p.distance} km to ${landmark}</span><span>${p.capacity>=4?'Family rooms':'Comfort for smaller groups'}</span></div><div class="amenities">`);html=html.replace('<div class="price-row">','<div class="cancellation-note">✓ Sample free cancellation up to 7 days before arrival</div><div class="price-row">');return html};
detail=function(id){let html=originalDetail(id);if(!selected)return html;html=html.replace('<div class="gallery">','<div class="gallery-toolbar"><span>Explore your space</span><div class="gallery-tabs" role="group" aria-label="Photo categories"><button class="active" onclick="changeGallery(\'all\',this)">All photos</button><button onclick="changeGallery(\'bedroom\',this)">Bedroom</button><button onclick="changeGallery(\'bathroom\',this)">Bathroom</button><button onclick="changeGallery(\'exterior\',this)">Exterior</button></div></div><div class="gallery">');html=html.replace('<h2>Good to know</h2>','<h2>Comfort begins with the details.</h2><div class="accessibility-note"><span class="line-icon">'+icons.shield+'</span><div><h3>Travelling with accessibility needs?</h3><p>Lift access, step-free entry, ground-floor rooms and accessible bathrooms have not been verified for this demo stay. Confirm these details with the property before making travel arrangements.</p><a class="text-link" href="#/support">Ask about your requirements ↗</a></div></div><h3>House rules & arrival</h3>');html+=`<div class="mobile-booking"><div><strong>${money(nightly())}</strong><small>/ night · sample price</small></div><button class="btn" onclick="document.querySelector('.booking-panel').scrollIntoView({behavior:'smooth',block:'center'})">Choose your stay →</button></div>`;return html};
function changeGallery(category,button){document.querySelectorAll('.gallery-tabs button').forEach(b=>b.classList.remove('active'));button.classList.add('active');let gallery=document.querySelector('.gallery');if(category==='all'){gallery.innerHTML=`<img src="${photo(selected.image,1400)}" alt="Illustrative property exterior"><div><img src="${photo(images.room,650)}" alt="Illustrative bedroom"><img src="${photo(images.bed,650)}" alt="Illustrative room interior"></div>`;gallery.classList.remove('single-photo');return}if(category==='bathroom'){gallery.innerHTML='<div class="gallery-unavailable"><span>◇</span><h3>Bathroom photos coming soon</h3><p>This demo listing has no verified bathroom photography.<br>Property owners will provide these images before launch.</p></div>';gallery.classList.add('single-photo');return}gallery.innerHTML=`<img src="${photo(category==='bedroom'?images.room:selected.image,1400)}" alt="Illustrative ${category} photograph, not a verified property image">`;gallery.classList.add('single-photo')}
function partnerLanding(){return `<section class="partner-hero"><div class="container partner-intro"><div><span class="eyebrow">Hospitality with a shared purpose</span><h1>Your place.<br>Their sacred journey.</h1><p>Welcome pilgrims and travellers to your hotel, homestay, dharamshala or tent accommodation in Nashik and Trimbakeshwar.</p><button class="btn" onclick="propertyForm()">Start your property listing ↗</button><a class="partner-login" href="#/owner">Already exploring? Open partner demo →</a></div><img src="${photo(images.room,1100)}" alt="Illustrative welcoming accommodation interior"></div></section><section class="section"><div class="container"><div class="section-heading"><div><span class="eyebrow">From your doorstep to their next chapter</span><h2>A thoughtful way to welcome guests.</h2></div></div><div class="partner-benefits">${[[icons.pin,'Reach the right travellers','Introduce your accommodation to people planning a stay around Nashik and Trimbakeshwar.'],[icons.leaf,'Your property, your details','Present room types, amenities, photographs and rates from a dedicated partner space.'],[icons.shield,'A clear review process','Property submissions go through administrative review before becoming publicly bookable.']].map(([i,t,d])=>`<article><div class="line-icon">${i}</div><h3>${t}</h3><p>${d}</p></article>`).join('')}</div></div></section><section class="section tinted"><div class="container"><span class="eyebrow">Getting started</span><h2 class="mt">Three steps to a warmer welcome.</h2><div class="onboarding-steps">${[['01','Tell us about your place','Add your property name, location, accommodation category and contact details.'],['02','Make your rooms shine','Provide room types, clear photographs, capacity, amenities, house rules and nightly rates.'],['03','Submit for review','Your details are reviewed before the property can accept real reservations.']].map(([n,t,d])=>`<article><span>${n}</span><h3>${t}</h3><p>${d}</p></article>`).join('')}</div></div></section><section class="section"><div class="container partner-bottom"><div><h2>Ready to open your doors?</h2><p class="notice">Start with a few details. You can refine your listing in the partner dashboard.</p></div><button class="btn" onclick="propertyForm()">Create a property draft ↗</button></div><div class="container">${demo}<p class="notice">This preview saves listing drafts in your browser only. Registration, verification, commissions, payments and settlements will be connected in the backend phase.</p></div></section>`}
render=function(){if(location.hash==='#/list-property'){$('#app').innerHTML=header()+`<main>${partnerLanding()}</main>`+footer();document.title='List your property · MahakumbhStays'}else originalRender();document.querySelectorAll('a[href="#/owner"]').forEach(a=>{if(a.textContent.includes('List your property'))a.href='#/list-property'});document.querySelectorAll('.brand-icon').forEach(el=>{el.innerHTML='<svg viewBox="0 0 40 40" aria-hidden="true"><path d="M20 4c-2 7-8 8-8 14 0 4 3 7 8 7s8-3 8-7c0-6-6-7-8-14Z"/><path d="M5 22c2 9 8 14 15 14s13-5 15-14c-6 0-11 3-15 9-4-6-9-9-15-9Z"/><path d="M20 25v11"/></svg>'});};render();
